solution.Solution.java:
public class Solution {
    static boolean isLeapYear(int year) {
        return year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
    }

    static String clock(int minutes) {
        int m = Math.floorMod(minutes, 1440);
        return String.format("%d:%02d", m / 60, m % 60);
    }

    static int coins(int cents, int coin) {
        return cents / coin;
    }

    static boolean canVote(int age, boolean isCitizen, boolean isRegistered) {
        return age >= 18 && isCitizen && isRegistered;
    }
}

unitTests:
test("leap years", () -> {
    checkEq(Solution.isLeapYear(2024), true);
    checkEq(Solution.isLeapYear(2023), false);
    checkEq(Solution.isLeapYear(1900), false);
    checkEq(Solution.isLeapYear(2000), true);
});

test("clock times", () -> {
    checkEq(Solution.clock(125), "2:05");
    checkEq(Solution.clock(0), "0:00");
    checkEq(Solution.clock(1439), "23:59");
    checkEq(Solution.clock(1440), "0:00");
    checkEq(Solution.clock(-30), "23:30");
    checkEq(Solution.clock(3000), "2:00");
});

test("coins", () -> {
    checkEq(Solution.coins(185, 50), 3);
    checkEq(Solution.coins(49, 50), 0);
    checkEq(Solution.coins(100, 25), 4);
});

test("voting", () -> {
    checkEq(Solution.canVote(18, true, true), true);
    checkEq(Solution.canVote(17, true, true), false);
    checkEq(Solution.canVote(30, false, true), false);
    checkEq(Solution.canVote(30, true, false), false);
});

